import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 20 One man in a boat","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 20 One man in a boat","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 19 Sold out","link":"/life/english/new-concept/book-2/unit-01/lesson-019"},"next":{"text":"第二册：实践与进步 · Lesson 21 Mad or not?","link":"/life/english/new-concept/book-2/unit-01/lesson-021"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 19 Sold out","link":"/life/english/new-concept/book-2/unit-01/lesson-019"},"next":{"text":"第二册：实践与进步 · Lesson 21 Mad or not?","link":"/life/english/new-concept/book-2/unit-01/lesson-021"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-020.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-020.md"}'),o={name:"life/english/new-concept/book-2/unit-01/lesson-020.md"};function s(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-20-one-man-in-a-boat" tabindex="-1">第二册：实践与进步 · Lesson 20 One man in a boat <a class="header-anchor" href="#第二册-实践与进步-·-lesson-20-one-man-in-a-boat" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 20 One man in a boat&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>钓鱼者重视安静的过程而不只在乎收获；练习用动名词描述爱好与介词后的活动。本课的语言观察是：enjoy 后接 fishing 而非 to fish；after spending 中 after 是介词，后面用动名词。描述兴趣时不需要把每个动作都写成进行时。完成学习后，请介绍一项不以结果为唯一目标的爱好，使用 enjoy doing 和一个动名词主语。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>fish</td><td>/fɪʃ/</td><td>v.</td><td>钓鱼</td><td>fish by the lake</td></tr><tr><td>boat</td><td>/bəʊt/</td><td>n.</td><td>船</td><td>a wooden boat</td></tr><tr><td>patient</td><td>/ˈpeɪʃənt/</td><td>adj.</td><td>耐心的</td><td>be patient</td></tr><tr><td>river</td><td>/ˈrɪvə/</td><td>n.</td><td>河流</td><td>cross a river</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be interested in — 对……感兴趣，in 后可接 -ing</li><li>spend time doing — 花时间做某事</li></ul><h2 id="语法讲解-动名词与动词搭配" tabindex="-1">语法讲解：动名词与动词搭配 <a class="header-anchor" href="#语法讲解-动名词与动词搭配" aria-label="Permalink to &quot;语法讲解：动名词与动词搭配&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：enjoy 后接 fishing 而非 to fish；after spending 中 after 是介词，后面用动名词。描述兴趣时不需要把每个动作都写成进行时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Ben enjoys fishing beside the old bridge.</p></blockquote><p>本喜欢在旧桥旁钓鱼。</p><p>enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 fishing 与 listening 的 /ɪŋ/，不要额外加 /ɡ/；在主语短语后自然停顿。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Ben enjoys fishing beside the old bridge. He rarely catches anything. Listening to the water is enough for him.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一项不以结果为唯一目标的爱好，使用 enjoy doing 和一个动名词主语。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 fish 的形式：Ben enjoys ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fishing</p><p><strong>解析：</strong> enjoy 通常接动名词作宾语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>本一定要钓到鱼才开心吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. Listening to the water is enough for him.</p><p><strong>解析：</strong> 示范强调过程本身的价值。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 He is interested in fish 改成“他对钓鱼感兴趣”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He is interested in fishing.</p><p><strong>解析：</strong> 介词 in 后用动名词，fish 名词则指鱼这一类事物。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词与动词搭配。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-019">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-021">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
